CREATE TABLE t1(a INT); CREATE TABLE t2(b INT,c INT); CREATE VIEW t3(d) AS SELECT NULL FROM t2 FULL OUTER JOIN t1 ON c=a UNION ALL SELECT b FROM t2; INSERT INTO t1(a) VALUES(NULL); INSERT INTO t2(b,c) VALUES(99,NULL); CREATE TABLE sfi_result AS SELECT DISTINCT b,c,d FROM t2,t3 WHERE b<>0 UNION SELECT DISTINCT b,c,d FROM t2,t3 WHERE b ISNULL;